/////////////////////////////////////////
// MODELS
/////////////////////////////////////////

/////////////////////////////////////////
// USER SCHEMA
/////////////////////////////////////////

/**
 * ユーザー情報を管理するテーブル
 */
export const UserSchema = z.object({
  /**
   * ユーザーID
   */
  id: z.cuid(),
  /**
   * 名前
   */
  name: z.string().nullable(),
  /**
   * メールアドレス (NextAuth: @unique が必須)
   */
  email: z.string().nullable(),
  /**
   * メール認証日時
   */
  emailVerified: z.coerce.date().nullable(),
  /**
   * アイコンURL
   */
  image: z.string().nullable(),
  /**
   * 作成日
   */
  createdAt: z.coerce.date(),
  /**
   * 更新日
   */
  updatedAt: z.coerce.date(),
})

export type User = z.infer<typeof UserSchema>

/////////////////////////////////////////
// ACCOUNT SCHEMA
/////////////////////////////////////////

/**
 * 認証連携用アカウント
 */
export const AccountSchema = z.object({
  /**
   * 内部ID
   */
  id: z.cuid(),
  /**
   * ユーザーID
   */
  userId: z.string(),
  /**
   * プロバイダー種別（NextAuthに必須）
   */
  type: z.string(),
  /**
   * プロバイダー名（google等）
   */
  provider: z.string(),
  /**
   * プロバイダー側のアカウントID
   */
  providerAccountId: z.string(),
  /**
   * リフレッシュトークン
   */
  refresh_token: z.string().nullable(),
  /**
   * アクセストークン
   */
  access_token: z.string().nullable(),
  /**
   * 有効期限
   */
  expires_at: z.number().int().nullable(),
  /**
   * トークン種別
   */
  token_type: z.string().nullable(),
  /**
   * スコープ
   */
  scope: z.string().nullable(),
  /**
   * IDトークン
   */
  id_token: z.string().nullable(),
  /**
   * セッション状態
   */
  session_state: z.string().nullable(),
})

export type Account = z.infer<typeof AccountSchema>

/////////////////////////////////////////
// SESSION SCHEMA
/////////////////////////////////////////

/**
 * セッション管理
 */
export const SessionSchema = z.object({
  /**
   * 内部ID
   */
  id: z.cuid(),
  /**
   * セッショントークン (NextAuth: @unique が必須)
   */
  sessionToken: z.string(),
  /**
   * ユーザーID
   */
  userId: z.string(),
  /**
   * 有効期限
   */
  expires: z.coerce.date(),
})

export type Session = z.infer<typeof SessionSchema>

/////////////////////////////////////////
// VERIFICATION TOKEN SCHEMA
/////////////////////////////////////////

/**
 * メール認証用トークン
 */
export const VerificationTokenSchema = z.object({
  /**
   * 識別子 (NextAuth: identifier に変更)
   */
  identifier: z.string(),
  /**
   * トークン (NextAuth: @unique が必須)
   */
  token: z.string(),
  /**
   * 有効期限
   */
  expires: z.coerce.date(),
})

export type VerificationToken = z.infer<typeof VerificationTokenSchema>

/////////////////////////////////////////
// COMPANY SCHEMA
/////////////////////////////////////////

/**
 * 企業情報を管理するテーブル
 */
export const CompanySchema = z.object({
  /**
   * 企業ID
   */
  id: z.cuid(),
  /**
   * ユーザーID
   */
  userId: z.string(),
  /**
   * 会社名
   */
  name: z.string(),
  /**
   * 設立年月日
   */
  establishedDate: z.coerce.date().nullable(),
  /**
   * 資本金
   */
  capital: z.bigint().nullable(),
  /**
   * 公式サイトURL
   */
  websiteUrl: z.string().nullable(),
  /**
   * 電話番号
   */
  phoneNumber: z.string().nullable(),
  /**
   * 総合評価スコア
   */
  ratingScore: z.number().int().nullable(),
  /**
   * 作成日時
   */
  createdAt: z.coerce.date(),
  /**
   * 更新日時
   */
  updatedAt: z.coerce.date(),
  /**
   * 志望度（0～5の5段階評価）
   */
  aspirationLevel: z.number().int().nullable(),
  /**
   * お気に入りフラグ
   */
  isFavorite: z.boolean(),
  /**
   * 閲覧回数
   */
  viewCount: z.number().int(),
})

export type Company = z.infer<typeof CompanySchema>

